import 'block_type.dart';
import 'hazard.dart';

/// All inputs needed to deterministically run one shift. Generated by
/// [DifficultyService.buildClassic] / [buildDaily] and consumed by
/// [PuzzleSession].
class ShiftConfig {
  const ShiftConfig({
    required this.id,
    required this.seed,
    required this.gridSize,
    required this.pieceQueueSize,
    required this.targetScore,
    required this.allowedTypes,
    required this.isDaily,
    this.duration,
    this.dailyModifier,
  });

  final String id;
  final int seed;
  final int gridSize;
  final int pieceQueueSize;

  /// Score the player needs to "complete" the shift. In Classic mode the
  /// shift is endless, but reaching this threshold flips
  /// [ShiftResult.completed] (which the economy uses for the daily bonus
  /// and which the result screen uses for celebratory copy).
  final int targetScore;

  final List<BlockType> allowedTypes;
  final bool isDaily;

  /// Optional time cap. Null in Classic mode (endless until game over).
  final Duration? duration;

  /// Active daily modifier (Daily Seal only). Null in Classic.
  final HazardKind? dailyModifier;
}
